using System;using System.IO;using System.Linq;using System.Globalization;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal sealed partial class MediaConverterWindow {
  internal readonly ComboBox SpeedPreset=new ComboBox{SelectedIndex=0},SpeedMethod=new ComboBox{SelectedIndex=0};internal readonly TextBox SpeedPercent=new TextBox{Text="100"},TargetLength=new TextBox{Text="01:00:00.000"};internal readonly TabItem SpeedTab=new TabItem();readonly TextBlock speedSummary=CopyUi.Label("");
  void InitializeSpeedControls(){string fractional=L.Language=="en"?"23.976":"23,976";SpeedPreset.ItemsSource=new[]{L.Text("media.speedOriginal"),fractional+" → 25 fps","24 → 25 fps","25 → "+fractional+" fps","25 → 24 fps",fractional+" → 24 fps","24 → "+fractional+" fps","50 %","75 %","125 %","150 %","200 %",L.Text("media.speedCustom"),L.Text("media.speedDuration")};SpeedMethod.ItemsSource=new[]{L.Text("media.speedPreserve"),L.Text("media.speedPitch")};SpeedPreset.SelectedIndex=SpeedMethod.SelectedIndex=0;var panel=new StackPanel();panel.Children.Add(Form("media.speedPreset",SpeedPreset,"media.speedPercent",SpeedPercent,"media.targetDuration",TargetLength,"media.speedMethod",SpeedMethod));speedSummary.TextWrapping=TextWrapping.Wrap;speedSummary.FontSize=11;speedSummary.Margin=new Thickness(0,0,0,2);panel.Children.Add(speedSummary);SpeedTab.Header=L.Text("media.speedTitle");SpeedTab.Content=panel;SettingsTabs.Items.Add(SpeedTab);SpeedPercent.ToolTip=L.Text("media.speedRange");TargetLength.ToolTip=L.Text("media.durationFormat");SpeedMethod.ToolTip=L.Text("media.speedRecommendation");ToolTipService.SetShowOnDisabled(keepVideo,true);SpeedPreset.SelectionChanged+=delegate{UpdateOptions();};SpeedMethod.SelectionChanged+=delegate{UpdateOptions();};SpeedPercent.TextChanged+=delegate{UpdateOptions();};TargetLength.TextChanged+=delegate{UpdateOptions();};files.SelectionChanged+=delegate{if(ready&&!running)UpdateOptions();};}
  internal double ReadSpeed(){int index=SpeedPreset.SelectedIndex;if(index<0||index>=AudioTempo.Factors.Length)throw new IOException(L.Text("media.speedInvalid"));if(index!=12)return AudioTempo.Factors[index];double percent;if(!Double.TryParse(SpeedPercent.Text.Replace(',','.'),NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out percent)||percent<10||percent>1000)throw new IOException(L.Text("media.speedInvalid"));return percent/100;}
  internal double ReadTargetDuration(){return SpeedPreset.SelectedIndex==13?AudioTempo.ParseDuration(TargetLength.Text):0;}
  void UpdateSpeedControls(bool image,bool pass){SpeedTab.Visibility=image?Visibility.Collapsed:Visibility.Visible;if(image&&SettingsTabs.SelectedItem==SpeedTab)SettingsTabs.SelectedIndex=0;bool changed=SpeedPreset.SelectedIndex!=0;if(changed){copy.IsChecked=false;keepVideo.IsChecked=false;}copy.IsEnabled=!changed;keepVideo.IsEnabled=((MediaProfile)Profile.SelectedItem).Video&&!changed;keepVideo.ToolTip=L.Text(changed?"media.speedVideoConflict":"media.audioHint");SpeedPreset.IsEnabled=!pass&&!running;SpeedPercent.IsEnabled=!pass&&!running&&SpeedPreset.SelectedIndex==12;TargetLength.IsEnabled=!pass&&!running&&SpeedPreset.SelectedIndex==13;SpeedMethod.IsEnabled=!pass&&!running&&changed;var row=files.SelectedItem as MediaRow;try{var options=AudioOptions();if(row!=null&&row.Info!=null&&!row.Image&&row.Info.Audio.Count>options.Track){double factor=MediaAudio.SpeedFactor(options,row.Info),source=MediaAudio.SourceDuration(options,row.Info);if(SpeedPreset.SelectedIndex!=12)SpeedPercent.Text=(factor*100).ToString("0.######",CultureInfo.CurrentCulture);if(SpeedPreset.SelectedIndex!=13&&source>0)TargetLength.Text=AudioTempo.Duration(source/factor);speedSummary.Text=L.Format("media.speedPreview",AudioTempo.Duration(source),AudioTempo.Duration(source/factor),(factor*100).ToString("0.####",CultureInfo.CurrentCulture));}else speedSummary.Text=L.Text("media.speedRecommendation");speedSummary.ToolTip=L.Text("media.speedRecommendation")+Environment.NewLine+L.Text("media.speedBatchHint");}catch(Exception ex){speedSummary.Text=ex.Message;}}
 }
}
